mapper.delete:
DELETE FROM BOK_BALANCE A
WHERE A.BOOKSET_ID = #{booksetId}
AND A.BALANCE_DATE >= #{startBookDate}

mapper.select:
SELECT bb.BOOKSET_ID as booksetId, /** 账套代码 **/ bb.STANDARD_CCY as standardCcy, /** 本位币 **/ #{BOOK_DATE,jdbcType=DATE} happenDate, /** 发生日 **/ #{HAPPEN_DATE,jdbcType=DATE} bookDate, /** 入账日 **/ CASE WHEN bbacl.CDATE IS NULL THEN financeCurrent.startBookDate ELSE CASE WHEN bbacl.CDATE >= #{BOOK_DATE,jdbcType=DATE} THEN #{BOOK_DATE,jdbcType=DATE} ELSE bbacl.CDATE + 1 END END startBookDate, /** 汇总开始日 **/ CASE WHEN financeCurrent.endBookDate > #{BOOKSET_DATE,jdbcType=DATE} THEN #{BOOKSET_DATE,jdbcType=DATE} ELSE financeCurrent.endBookDate END endBookDate /** 汇总结束日 **/ from BOK_BOOKSET bb /** 账套 **/ left join bok_bookset_re bbr /** 母子账套关系 **/ on bb.bookset_id = bbr.bookset_id LEFT JOIN BOK_BALANCE_AGAIN_COLLECT_LOG bbacl /** 科目余额汇总信息记录表 **/ ON bb.bookset_id = bbacl.bookset_id LEFT JOIN ( SELECT BBC.BOOKSET_ID, MIN(BBC.BOOK_DATE) startBookDate, /** 开始入账日 **/ MAX(BBC.BOOK_DATE) endBookDate /** 结束入账日期 **/ FROM BOK_BOOKDETAIL_CURRENT BBC /** 账务当前表 **/ GROUP BY BBC.Bookset_Id ) financeCurrent ON financeCurrent.BOOKSET_ID = bb.BOOKSET_ID
where 1 = 1 and (
bb.bookset_id in (
#{item, jdbcType=VARCHAR}
)
OR
bbr.bookset_id in (
#{item, jdbcType=VARCHAR} )
)
